        /// <summary>Central-difference Jacobian of <paramref name="model"/>.F at (x, u): J[:,k] =
        /// (F(x+eps·e_k,u) - F(x-eps·e_k,u)) / (2·eps). Call from inside a
        /// <see cref="IfloatKFModel.JacobianF"/> implementation. J must be n x n.</summary>
        public static void numericJacobianF<TModel>(in TModel model, in floatN x, in floatN u, ref floatMxN J, float eps)
            where TModel : struct, IfloatKFModel
        {
            int n = x.N;
            if (!J.IsSquare || J.M_Rows != n)
                throw new ArgumentException("Kalman.numericJacobianF: J must be n x n");

            var xp = new floatN(n, Allocator.Temp);
            var xm = new floatN(n, Allocator.Temp);
            var fp = new floatN(n, Allocator.Temp);
            var fm = new floatN(n, Allocator.Temp);

            for (int k = 0; k < n; k++)
            {
                xp.CopyFrom(in x);
                xm.CopyFrom(in x);
                xp[k] += eps;
                xm[k] -= eps;
                model.F(in xp, in u, ref fp);
                model.F(in xm, in u, ref fm);
                for (int i = 0; i < n; i++)
                    J[i, k] = (fp[i] - fm[i]) / ((float)2 * eps);
            }

            xp.Dispose(); xm.Dispose(); fp.Dispose(); fm.Dispose();
        }

