            {
                xp.CopyFrom(in x);
                xm.CopyFrom(in x);
                xp[k] += eps;
                xm[k] -= eps;
                meas.H(in xp, ref hp);
                meas.H(in xm, ref hm);
                for (int i = 0; i < m; i++)
                    J[i, k] = (hp[i] - hm[i]) / ((float)2 * eps);
            }

            xp.Dispose(); xm.Dispose(); hp.Dispose(); hm.Dispose();
        }

        /// <summary>Overload of <see cref="numericJacobianH{TMeas}(in TMeas, in floatN, ref floatMxN, float)"/>
        /// using <see cref="Consts.floatSqrtEps"/> as the finite-difference step.</summary>
        public static void numericJacobianH<TMeas>(in TMeas meas, in floatN x, ref floatMxN J)
            where TMeas : struct, IfloatKFMeasurement
            => numericJacobianH(in meas, in x, ref J, Consts.floatSqrtEps);
    }
}
